const bEl=()=>B.acc+(B.run?Date.now()-B.start:0);const mmss=s=>{s=Math.max(0,s);return String(Math.floor(s/60)).padStart(2,"0")+":"+String(Math.floor(s%60)).padStart(2,"0")};
function tick(){if(!B)return;const s=bEl()/1000;if(B.phase==="timed"){let idx=0;B.timed.forEach((x,i)=>{if(s>=x.at)idx=i});if(idx!==B.last){B.last=idx;beep();drawBrew()}else updClock();if(s>=B.end){clearInterval(B.run);B.run=null;B.acc=B.end*1000;beep();B.phase=B.after.length?"after":"done";B.i=0;drawBrew()}}else updClock()}
