 if(B.phase==="prep"||B.phase==="after"){dots=steps.map((_,i)=>`<span class="${i<B.i?"done":i===B.i?"on":""}"></span>`).join("");
  phaseLbl=B.phase==="prep"?t("prepPhase"):t("method");body=`<div class="small">${t("stepOf",{a:B.i+1,b:steps.length})}</div><div class="steptxt">${esc(steps[B.i]||"")}</div>${B.free?`<div class="small">${t("stopwatch")}</div><div class="clock" id="bClock" style="font-size:52px">${mmss(bEl()/1000)}</div>`:""}`;
  const last=B.i>=steps.length-1;ctrl=`<button class="btn" id="bPrevB" ${B.i===0?"disabled":""}>${t("bPrev")}</button>${B.free?`<button class="btn" id="bSw">${B.run?t("bPause"):t("bStartTimer")}</button>`:""}<button class="btn primary" id="bNextB">${last?(B.phase==="prep"&&B.timed?t("bNext")+" →":t("bFinish")):t("bNext")}</button>`}
 else if(B.phase==="timed"){const cur=B.timed[Math.max(0,B.last)];phaseLbl=t("timedPhase");dots=B.timed.map((_,i)=>`<span class="${i<B.last?"done":i===B.last?"on":""}"></span>`).join("");
  body=`<div class="clock" id="bClock">${mmss(bEl()/1000)}</div><div class="bar"><i id="bBar"></i></div><div class="steptxt">${esc(B.run||B.acc?tx(cur.t):tx(B.timed[0].t))}</div>${cur.g&&(B.run||B.acc)?`<span class="tgt">${t("target")}: <bdi dir="ltr">${esc(cur.g)}</bdi></span>`:""}<div class="small" id="bNext"></div>`;
  ctrl=`<button class="btn" id="bPrevB">${t("bPrev")}</button><button class="btn primary" id="bRun">${B.run?t("bPause"):B.acc?t("bResume"):t("bStartTimer")}</button><button class="btn" id="bSkip">${t("bNext")} ⏭</button>`}
 else{phaseLbl="✓";body=`<div class="steptxt" style="font-size:30px;color:var(--gold)">${t("brewDone")}</div>${B.timed?`<div class="clock" style="font-size:52px">${mmss(bEl()/1000)}</div>`:""}`;ctrl=`${B.shot?`<button class="btn" id="bLog">${t("bSaveShotLog")}</button>`:""}<button class="btn primary" id="bClose2">${t("bFinish")}</button>`}
 $("#brew").innerHTML=`<div class="top"><div><div class="phase">${t("brewTitle")} · ${phaseLbl}</div><b style="color:#f1dcb8;font-size:18px">${esc(rName(r))}</b></div><div style="display:flex;gap:8px"><button class="pill ${beepOn?"on":""}" id="bBeep">${t("soundOn")}</button><button class="close" style="position:static" id="bClose" aria-label="close">✕</button></div></div><div class="stage">${body}<div class="dots">${dots}</div><div class="ctrl">${ctrl}</div></div>`;
