 on("bSkip",()=>{const n=B.timed[B.last+1];if(n){B.acc=n.at*1000;if(B.run)B.start=Date.now();tick();drawBrew()}else{B.acc=B.end*1000;if(B.run)B.start=Date.now();tick()}});
 on("bLog",()=>{const e=B.r.ext||{};S.shots.unshift({id:uid(),date:Date.now(),coffee:rName(B.r),dose:Number(e.dose)||18,yield:Number(e.yield)||36,time:Math.round(bEl()/100)/10||30,temp:"93",press:"9",grind:"",notes:t("brewTitle")});save("shots");renderShots();toast(t("tSaved"));closeBrew()});
