function renderMake(){$("#makeChips").innerHTML=ING.map(([k,ic,lb])=>`<button class="itile ${have.has(k)?"on":""}" data-ing="${k}" aria-pressed="${have.has(k)}"><span class="med"><svg viewBox="0 0 24 24"><path d="${ING_ICONS[k]||ING_ICONS.coffee}"/></svg></span><span class="nm">${esc(tx(lb))}</span><span class="ck">✓</span></button>`).join("");
 if(!have.size){$("#makeOut").innerHTML=`<div class="empty">${t("makeNone")}</div>`;return}
 const now=[],almost=[];allRecipes().forEach(r=>{const n=needsOf(r);if(!n.length)return;const miss=n.filter(x=>!have.has(x));if(!miss.length)now.push(r);else if(miss.length===1)almost.push([r,miss[0]])});
 const lbl=k=>{const x=ING.find(i=>i[0]===k);return x?x[1]+" "+tx(x[2]):k};
 $("#makeOut").innerHTML=`<h3 class="sub"><span style="color:var(--gold)">✦</span> ${t("makeNow")} (${now.length})</h3>${now.length?`<div class="grid r">${now.map(r=>recipeCard(r)).join("")}</div>`:`<div class="empty">—</div>`}
 ${almost.length?`<h3 class="sub"><span style="color:var(--gold)">✧</span> ${t("makeAlmost")} (${almost.length})</h3><div class="grid r">${almost.map(([r,m])=>recipeCard(r).replace('<div class="rbody">',`<div class="rbody"><div class="small" style="color:var(--red);margin-bottom:4px">${t("missing")} ${esc(lbl(m))}</div>`)).join("")}</div>`:""}`;hydrate($("#makeOut"))}
$("#makeChips").addEventListener("click",e=>{const b=e.target.closest("[data-ing]");if(!b)return;const k=b.dataset.ing;have.has(k)?have.delete(k):have.add(k);try{localStorage.setItem("bb_have",JSON.stringify([...have]))}catch(err){}renderMake()});
$("#makeAll").addEventListener("click",()=>{have=new Set(ING.map(i=>i[0]));try{localStorage.setItem("bb_have",JSON.stringify([...have]))}catch(e){}renderMake()});
$("#makeClear").addEventListener("click",()=>{have=new Set();try{localStorage.setItem("bb_have","[]")}catch(e){}renderMake()});

