let QZ=null;
function quizStats(){if(!S.quiz||Array.isArray(S.quiz))S.quiz={};return S.quiz}
function renderQuiz(){const st=quizStats();const head=`<div class="res-grid" style="margin:0 0 14px"><div class="card"><p>${t("bestScore")}</p><div class="result">${st.best??"—"}${st.best!=null?" / 10":""}</div></div><div class="card"><p>${t("streak")}</p><div class="result">🔥 ${st.streak||0}</div></div></div>`;
 if(!QZ){$("#quizBody").innerHTML=head+`<div class="box"><p style="margin-top:0">${t("quizIntro")}</p><div class="actions"><button class="btn primary" id="qStart">${t("bStartQuiz")}</button><button class="btn" id="qFlash">🃏 ${t("bFlash")}</button></div></div>`;$("#qStart").onclick=startQuiz;$("#qFlash").onclick=startFlash;return}
 if(QZ.mode==="flash"){const q=QB[QZ.order[QZ.i]];$("#quizBody").innerHTML=head+`<div class="flash"><div class="small" style="text-align:center;margin-bottom:8px">${QZ.i+1} / ${QZ.order.length} · ${t("flip")}</div><div class="fc" id="fc"><div class="side">${esc(tx(q[0]))}</div><div class="side back"><span class="small">${t("answer")}</span><b>${esc(tx(q[1][q[2]]))}</b><p>${esc(tx(q[3]))}</p></div></div><div class="actions" style="justify-content:center"><button class="btn" id="fPrev">${t("bPrev")}</button><button class="btn primary" id="fNext">${t("bNext")}</button><button class="btn" id="fExit">✕</button></div></div>`;
  $("#fc").onclick=()=>$("#fc").classList.toggle("flipped");$("#fPrev").onclick=()=>{QZ.i=(QZ.i-1+QZ.order.length)%QZ.order.length;renderQuiz()};$("#fNext").onclick=()=>{QZ.i=(QZ.i+1)%QZ.order.length;renderQuiz()};$("#fExit").onclick=()=>{QZ=null;renderQuiz()};return}
 if(QZ.i>=QZ.order.length){$("#quizBody").innerHTML=head+`<div class="box" style="text-align:center"><div class="result" style="font-size:40px">${QZ.score} / ${QZ.order.length}</div><p>${t("score",{s:QZ.score,n:QZ.order.length})}</p><div class="actions" style="justify-content:center"><button class="btn primary" id="qAgain">${t("bAgain")}</button><button class="btn" id="qFlash2">🃏 ${t("bFlash")}</button></div></div>`;$("#qAgain").onclick=startQuiz;$("#qFlash2").onclick=startFlash;return}
 const q=QB[QZ.order[QZ.i]];$("#quizBody").innerHTML=head+`<div class="box"><div class="small">${t("qOf",{a:QZ.i+1,b:QZ.order.length})} · ✓ ${QZ.score}</div><div class="bar" style="height:5px;background:#2b241b;border-radius:9px;margin:8px 0 14px;overflow:hidden"><i style="display:block;height:100%;width:${QZ.i/QZ.order.length*100}%;background:var(--gold)"></i></div><h3 style="margin:0 0 6px;color:#f1dcb8">${esc(tx(q[0]))}</h3>${q[1].map((o,i)=>`<button class="qopt" data-qi="${i}">${esc(tx(o))}</button>`).join("")}<div id="qFeed"></div></div>`;
 $$(".qopt").forEach(b=>b.onclick=()=>{const i=+b.dataset.qi,ok=i===q[2];$$(".qopt").forEach(x=>{x.disabled=true;const j=+x.dataset.qi;if(j===q[2])x.classList.add("ok");else if(j===i)x.classList.add("no")});if(ok)QZ.score++;
  $("#qFeed").innerHTML=`<div class="note"><b class="${ok?"pos":"neg"}">${ok?t("correct"):t("wrong")}</b> — ${esc(tx(q[3]))}</div><div class="actions"><button class="btn primary" id="qNext">${t("bNext")}</button></div>`;$("#qNext").onclick=()=>{QZ.i++;if(QZ.i>=QZ.order.length)finishQuiz();renderQuiz()}})}
const shuffle=a=>{a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
function startQuiz(){QZ={mode:"quiz",order:shuffle(QB.map((_,i)=>i)).slice(0,10),i:0,score:0};renderQuiz()}
function startFlash(){QZ={mode:"flash",order:shuffle(QB.map((_,i)=>i)),i:0};renderQuiz()}
function finishQuiz(){const st=quizStats(),d=dayIndex();st.best=Math.max(st.best||0,QZ.score);if(st.lastDay!==d){st.streak=st.lastDay===d-1?(st.streak||0)+1:1;st.lastDay=d}st.played=(st.played||0)+1;save("quiz")}

