let flavSel=null;
function arc(r1,r2,a1,a2){const p=(r,a)=>[r*Math.cos(a),r*Math.sin(a)];const[x1,y1]=p(r2,a1),[x2,y2]=p(r2,a2),[x3,y3]=p(r1,a2),[x4,y4]=p(r1,a1);const lg=a2-a1>Math.PI?1:0;return`M${x1} ${y1}A${r2} ${r2} 0 ${lg} 1 ${x2} ${y2}L${x3} ${y3}A${r1} ${r1} 0 ${lg} 0 ${x4} ${y4}Z`}
function renderFlavor(animate){const n=FLAV.length,step=2*Math.PI/n,off=-Math.PI/2;let g1="",g2="";
 FLAV.forEach((f,i)=>{const a1=off+i*step,a2=a1+step,mid=(a1+a2)/2,sel=flavSel===f.k;const lx=Math.cos(mid)*88,ly=Math.sin(mid)*88;
  g1+=`<g class="${sel?"sel":""}" data-fk="${f.k}"><path d="${arc(45,130,a1,a2)}" fill="${f.c}" opacity="${flavSel&&!sel?.45:1}"/><text x="${lx}" y="${ly}" text-anchor="middle" dominant-baseline="middle">${esc(tx(f.n))}</text></g>`;
  const ss=step/f.s.length;f.s.forEach((s,j)=>{const b1=a1+j*ss,b2=b1+ss,m=(b1+b2)/2,deg=m*180/Math.PI;const flip=deg>90&&deg<270;const tx_=Math.cos(m)*168,ty=Math.sin(m)*168;
   g2+=`<g data-fk="${f.k}"><path d="${arc(132,205,b1,b2)}" fill="${f.c}" opacity="${flavSel&&!sel?.3:.78}"/><text x="${tx_}" y="${ty}" text-anchor="middle" dominant-baseline="middle" transform="rotate(${flip?deg+180:deg} ${tx_} ${ty})" style="font-size:10px">${esc(tx(s))}</text></g>`})});
 $("#wheel").innerHTML=`<g class="${animate?"spin":""}"><g class="ring2">${g2}</g><g class="ring1">${g1}</g><circle r="43" fill="#141110" stroke="#d3ad76" stroke-width="1.5"/><text y="-4" text-anchor="middle" style="fill:#d3ad76;font-size:13px;font-family:Georgia">${LANG==="ar"?"النكهات":"Flavor"}</text><text y="12" text-anchor="middle" style="fill:#b6a895;font-size:9px">BARISTA</text></g>`;
 const f=FLAV.find(x=>x.k===flavSel);
 $("#flavorInfo").innerHTML=!f?`<div class="empty" style="height:100%;display:grid;place-items:center">🎡 ${t("flavorPick")}</div>`:`<span class="tag" style="background:${f.c};color:#fff;border-color:${f.c}">${esc(tx(f.n))}</span><h3 style="margin:4px 0;color:#f1dcb8;font-size:22px">${esc(tx(f.n))}</h3><p style="color:#e2d4c0;margin:0 0 8px">${esc(tx(f.d))}</p>
 <div class="kv"><span><i>${t("fNotes")}</i> ${f.s.map(tx).map(esc).join("، ")}</span></div><div class="kv"><span><i>${t("fOrigins")}</i> ${esc(tx(f.o))}</span><span><i>${t("fProcess")}</i> ${esc(tx(f.p))}</span><span><i>${t("fRoast")}</i> ${esc(tx(f.r))}</span></div>
 <h3 class="sub">${t("fTry")}</h3><div class="hrow">${f.t.map(findRecipe).filter(Boolean).map(r=>`<div class="mini" data-act="open" data-id="${r.id}"><div class="im">${imgOf(r)}</div><div class="tx">${esc(rName(r))}</div></div>`).join("")}</div>`;hydrate($("#flavorInfo"))}
$("#wheel").addEventListener("click",e=>{const g=e.target.closest("[data-fk]");if(!g)return;flavSel=flavSel===g.dataset.fk?null:g.dataset.fk;renderFlavor(false)});

/* ---------- dashboard ---------- */
function barChart(vals,labels,h=150){const W=560,max=Math.max(1,...vals),bw=W/vals.length;return`<svg class="chart" viewBox="0 0 ${W} ${h+22}">${vals.map((v,i)=>{const bh=v/max*(h-14);return`<rect x="${i*bw+4}" y="${h-bh}" width="${bw-8}" height="${Math.max(bh,1)}" rx="4" fill="${v?"url(#gg)":"#2b241b"}"><title>${labels[i]}: ${v}</title></rect>${v?`<text x="${i*bw+bw/2}" y="${h-bh-4}" text-anchor="middle" style="fill:#f1dcb8">${v}</text>`:""}<text x="${i*bw+bw/2}" y="${h+15}" text-anchor="middle">${labels[i]}</text>`}).join("")}<defs><linearGradient id="gg" x1="0" y1="1" x2="0" y2="0"><stop offset="0" stop-color="#8a6a42"/><stop offset="1" stop-color="#e4c396"/></linearGradient></defs></svg>`}
function lineChart(a,b,labA,labB){const W=560,H=150,n=a.length;if(n<2)return"";const sc=(arr)=>{const mn=Math.min(...arr),mx=Math.max(...arr),r=mx-mn||1;return arr.map((v,i)=>[20+i*(W-40)/(n-1),H-12-(v-mn)/r*(H-30)])};const pa=sc(a),pb=sc(b);const path=p=>p.map((q,i)=>(i?"L":"M")+q[0].toFixed(1)+" "+q[1].toFixed(1)).join("");
 return`<svg class="chart" viewBox="0 0 ${W} ${H+20}"><path d="${path(pb)}" fill="none" stroke="#8fc79a" stroke-width="2" stroke-dasharray="5 4" opacity=".8"/><path d="${path(pa)}" fill="none" stroke="#e4c396" stroke-width="2.5"/>${pa.map((q,i)=>`<circle cx="${q[0]}" cy="${q[1]}" r="3.5" fill="#e4c396"><title>1:${a[i].toFixed(2)}</title></circle>`).join("")}<text x="20" y="${H+16}" style="fill:#e4c396">— ${labA}</text><text x="200" y="${H+16}" style="fill:#8fc79a">- - ${labB}</text></svg>`}
function renderDash(){const now=Date.now(),sh=S.shots||[];const wk=sh.filter(s=>now-s.date<7*864e5).length;const last=sh.slice(0,10).filter(s=>s.dose);const avgR=last.length?last.reduce((a,s)=>a+s.yield/s.dose,0)/last.length:0;const tm=sh.slice(0,10).filter(s=>s.time);const avgT=tm.length?tm.reduce((a,s)=>a+s.time,0)/tm.length:0;const qs=quizStats();
 const days=[...Array(14)].map((_,i)=>{const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-13+i);return d});const counts=days.map(d=>sh.filter(s=>{const x=new Date(s.date);x.setHours(0,0,0,0);return x.getTime()===d.getTime()}).length);const labels=days.map(d=>d.getDate()+"");
 const l15=sh.slice(0,15).filter(s=>s.dose&&s.time).reverse();
 const calcs=(S.costs||[]).map(c=>{const n=costNumbers(c.rows,c.op,c.price,c.vat);return{name:c.name,m:n.net?n.profit/n.net*100:0,p:n.profit}}).sort((a,b)=>b.m-a.m).slice(0,6);
 $("#dashBody").innerHTML=`<div class="res-grid" style="margin-top:0"><div class="card"><p>${t("dashShots7")}</p><div class="result">${wk}</div></div><div class="card"><p>${t("dashAvgRatio")}</p><div class="result" dir="ltr">${avgR?"1:"+avgR.toFixed(2):"—"}</div></div><div class="card"><p>${t("dashAvgTime")}</p><div class="result">${avgT?avgT.toFixed(1)+"s":"—"}</div></div><div class="card"><p>${t("dashRecipes")}</p><div class="result">${S.recipes.length}</div></div><div class="card"><p>${t("dashQuizBest")}</p><div class="result" dir="ltr" style="text-align:start">${qs.best??"—"} · 🔥${qs.streak||0}</div></div></div>
 ${!sh.length&&!calcs.length?`<div class="empty" style="margin-top:14px">${t("dashEmpty")}</div>`:""}
 ${sh.length?`<div class="cols2" style="margin-top:14px"><div class="box"><h3 class="bt">${t("dashShotsChart")}</h3>${barChart(counts,labels)}</div><div class="box"><h3 class="bt">${t("dashRatioChart")}</h3>${l15.length>1?lineChart(l15.map(s=>s.yield/s.dose),l15.map(s=>s.time),t("thRatio"),t("thTime")):`<p class="small">—</p>`}</div></div>`:""}
 ${calcs.length?`<div class="box" style="margin-top:14px"><h3 class="bt">${t("dashMargins")}</h3>${calcs.map(c=>`<div style="margin:10px 0"><div style="display:flex;justify-content:space-between;font-size:13.5px"><span>${esc(c.name)}</span><b class="${c.m<0?"neg":"pos"}" dir="ltr">${c.m.toFixed(1)}% · ${money(c.p)}</b></div><div style="height:8px;border-radius:9px;background:#2b241b;overflow:hidden;margin-top:4px"><i style="display:block;height:100%;width:${Math.max(0,Math.min(100,c.m))}%;background:linear-gradient(90deg,#8a6a42,#e4c396)"></i></div></div>`).join("")}</div>`:""}`}

